import{_ as l,o as i,c as s,a2 as r}from"./chunks/framework.CNDaxUod.js";const n="/docs/assets/i1.zlxjrWsa.png",t="/docs/assets/i2.CHUR5yQy.png",c="/docs/assets/i3.oW0g3FHN.png",a="/docs/assets/i4.9w7Goy63.png",o="/docs/assets/i5.Bi-C-F_B.png",k=JSON.parse('{"title":"How to install the SCTP mod?","description":"","frontmatter":{},"headers":[],"relativePath":"installation.md","filePath":"installation.md"}'),d={name:"installation.md"};function h(u,e,m,p,f,g){return i(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="how-to-install-the-sctp-mod" tabindex="-1">How to install the SCTP mod? <a class="header-anchor" href="#how-to-install-the-sctp-mod" aria-label="Permalink to &quot;How to install the SCTP mod?&quot;">​</a></h1><details class="details custom-block"><summary>Table of Contents/Overview</summary><nav class="table-of-contents"><ul><li><a href="#select-your-mod-loader">Select your mod loader</a></li></ul></nav></details><div class="danger custom-block"><p class="custom-block-title">1.21.11 &amp; 26.1 EOL</p><p>Minecraft version 1.21.11 and 26.1 are no longer supported as of version 1.6, but older downloads are still available for Fabric.</p></div><h2 id="select-your-mod-loader" tabindex="-1">Select your mod loader <a class="header-anchor" href="#select-your-mod-loader" aria-label="Permalink to &quot;Select your mod loader&quot;">​</a></h2><details class="details custom-block"><summary>Fabric</summary><h2 id="installing-fabric" tabindex="-1">Installing Fabric <a class="header-anchor" href="#installing-fabric" aria-label="Permalink to &quot;Installing Fabric&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Important:</p><p>This tutorial assumes you are using the default MC launcher. If you use Modrinth, Prism, Lunar, Feather, or a similar modded launcher, a different method may apply. I recommend you to use Google if that is the case.</p></div><h3 id="downloading-running-the-installer" tabindex="-1">Downloading &amp; running the installer <a class="header-anchor" href="#downloading-running-the-installer" aria-label="Permalink to &quot;Downloading &amp; running the installer&quot;">​</a></h3><p>Start by downloading and running the <a href="https://fabricmc.net/use/installer/" target="_blank" rel="noreferrer">official Fabric installer</a>. You will see a screen like this: <img src="'+n+'" alt="1"></p><div class="tip custom-block"><p class="custom-block-title">I: Please select the Minecraft version. For the SCTP mod, select 26.2 or 26.3.</p></div><div class="tip custom-block"><p class="custom-block-title">II: Please select the most recent loader version available, usually selected by default.</p></div><div class="tip custom-block"><p class="custom-block-title">III: Please make sure the Launcher Location is correct. Usually, the default will be correct.</p></div><div class="tip custom-block"><p class="custom-block-title">IV: Make sure &#39;Create profile&#39; is checked, and press &#39;Install&#39;.</p></div><h3 id="launching-minecraft" tabindex="-1">Launching Minecraft <a class="header-anchor" href="#launching-minecraft" aria-label="Permalink to &quot;Launching Minecraft&quot;">​</a></h3><p>Run the new profile created by the launcher first, so it can make the mods folder. Make sure the correct profile is selected (fabric-loader-XXX) and press play. <img src="'+t+'" alt="2"></p><h2 id="downloading-the-fabric-api" tabindex="-1">Downloading the Fabric API <a class="header-anchor" href="#downloading-the-fabric-api" aria-label="Permalink to &quot;Downloading the Fabric API&quot;">​</a></h2><p>Next up, we will download the Fabric API - it&#39;s a mod that is required for the SCTP mod to function. Start by going to the page on <a href="https://www.curseforge.com/minecraft/mc-mods/fabric-api" target="_blank" rel="noreferrer">curseforge</a>. <img src="'+c+'" alt="alt text"></p><div class="tip custom-block"><p class="custom-block-title">I: Select the same game version you picked during the installation process, in this case 26.2 or 26.3.</p></div><div class="tip custom-block"><p class="custom-block-title">II: Press download, and put the file in a place you will remember for later.</p></div><h2 id="downloading-the-sctp-mod" tabindex="-1">Downloading the SCTP mod <a class="header-anchor" href="#downloading-the-sctp-mod" aria-label="Permalink to &quot;Downloading the SCTP mod&quot;">​</a></h2><p>Next, we will download the SCTP mod, called shoplogger. You can download it by going to the <a href="https://sctp.nl/" target="_blank" rel="noreferrer">sctp homepage</a> and pressing the Download button.</p><div class="tip custom-block"><p class="custom-block-title">I: Select the correct game version (26.2 or 26.3) and put it in a place to remember for later.</p></div><p><img src="'+a+'" alt="alt text"></p><div class="info custom-block"><p class="custom-block-title">Safety</p><p>If you want to confirm the source code yourself before downloading, you can check out the <a href="https://github.com/maxolotled/sctp" target="_blank" rel="noreferrer">github repository</a>.</p></div><h2 id="installing-the-mod-files" tabindex="-1">Installing the mod files <a class="header-anchor" href="#installing-the-mod-files" aria-label="Permalink to &quot;Installing the mod files&quot;">​</a></h2><p>For the last step, we need to put the mod files into the directory of the Fabric installation we made. Start by navigating to where you put the two downloaded mod files. <img src="'+o+'" alt="alt text"></p><div class="tip custom-block"><p class="custom-block-title">I: Copy the mod files: one for fabric API and one for SCTP.</p></div><div class="tip custom-block"><p class="custom-block-title">II: Navigate to the mod directory by pasting <code>%appdata%\\.minecraft\\mods</code> in your navigator bar (marked with the arrow), or open the folder via your launcher</p></div><div class="tip custom-block"><p class="custom-block-title">III: Paste the files into this mods folder.</p></div><h2 id="done" tabindex="-1">Done <a class="header-anchor" href="#done" aria-label="Permalink to &quot;Done&quot;">​</a></h2><p>Congratulations, you have successfully installed the SCTP mod into your Minecraft, and can now start using it! Thank you for helping maintain the website. Check out the <a href="./features">features</a> now!</p></details><details class="details custom-block"><summary>Neoforge</summary><h2 id="installing-neoforge" tabindex="-1">Installing NeoForge <a class="header-anchor" href="#installing-neoforge" aria-label="Permalink to &quot;Installing NeoForge&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Important:</p><p>This tutorial assumes you are using the default MC launcher. If you use Modrinth, Prism, Lunar, Feather, or a similar modded launcher, a different method may apply. I recommend you to use Google if that is the case.</p></div><h3 id="downloading-running-the-installer-1" tabindex="-1">Downloading &amp; running the installer <a class="header-anchor" href="#downloading-running-the-installer-1" aria-label="Permalink to &quot;Downloading &amp; running the installer&quot;">​</a></h3><p>Start by downloading and running the <a href="https://neoforged.net/" target="_blank" rel="noreferrer">official Neoforge installer</a>.</p><div class="tip custom-block"><p class="custom-block-title">Please select the correct Minecraft version on the website - 26.2 or 26.3</p></div><div class="tip custom-block"><p class="custom-block-title">Please select the most recent loader version available, usually selected by default.</p></div><p>After opening the installer, make sure to:</p><div class="tip custom-block"><p class="custom-block-title">Select &#39;Install client&#39;</p></div><div class="tip custom-block"><p class="custom-block-title">Keep the directory the same if you use the normal MC launcher without changing the location.</p></div><p>After letting the installer do it&#39;s work, Neoforge will be installed succesfully!</p><h3 id="launching-minecraft-1" tabindex="-1">Launching Minecraft <a class="header-anchor" href="#launching-minecraft-1" aria-label="Permalink to &quot;Launching Minecraft&quot;">​</a></h3><p>Run the new profile created by the launcher first, so it can make the mods folder. Make sure the correct profile is selected (Neoforge-XXX-loader-XXX, or similar) and press play. <img src="'+t+'" alt="2"></p><h2 id="downloading-the-sctp-mod-1" tabindex="-1">Downloading the SCTP mod <a class="header-anchor" href="#downloading-the-sctp-mod-1" aria-label="Permalink to &quot;Downloading the SCTP mod&quot;">​</a></h2><p>Next, we will download the SCTP mod, called shoplogger. You can download it by going to the <a href="https://sctp.nl/" target="_blank" rel="noreferrer">sctp homepage</a> and pressing the Download button.</p><div class="tip custom-block"><p class="custom-block-title">I: Select the correct game version (26.2 or 26.3) and put it in a place to remember for later. Make sure to select Neoforge.</p></div><p><img src="'+a+'" alt="alt text"></p><div class="info custom-block"><p class="custom-block-title">Safety</p><p>If you want to confirm the source code yourself before downloading, you can check out the <a href="https://github.com/maxolotled/sctp" target="_blank" rel="noreferrer">github repository</a>.</p></div><h2 id="installing-the-mod-files-1" tabindex="-1">Installing the mod files <a class="header-anchor" href="#installing-the-mod-files-1" aria-label="Permalink to &quot;Installing the mod files&quot;">​</a></h2><p>For the last step, we need to put the mod files into the directory of the Fabric installation we made. Start by navigating to where you put the two downloaded mod files. <img src="'+o+'" alt="alt text"></p><div class="tip custom-block"><p class="custom-block-title">I: Copy the SCTP mod file you just downloaded.</p></div><div class="tip custom-block"><p class="custom-block-title">II: Navigate to the mod directory by pasting <code>%appdata%\\.minecraft\\mods</code> in your navigator bar (marked with the arrow), or open the folder via your launcher</p></div><div class="tip custom-block"><p class="custom-block-title">III: Paste the files into this mods folder.</p></div><h2 id="done-1" tabindex="-1">Done <a class="header-anchor" href="#done-1" aria-label="Permalink to &quot;Done&quot;">​</a></h2><p>Congratulations, you have successfully installed the SCTP mod into your Minecraft, and can now start using it! Thank you for helping maintain the website. Check out the <a href="./features">features</a> now!</p></details>',6)])])}const w=l(d,[["render",h]]);export{k as __pageData,w as default};
